// Input is valid HTML generated by our formatters. Bound encoded length while
// keeping tags, entities and UTF-16 pairs intact; no delivery or retry effects.
function truncateTelegramHtml(value: string, maxLength: number): string {
  if (!Number.isInteger(maxLength) || maxLength < 20) {
    throw new RangeError('Telegram HTML limit must be an integer >= 20')
  }
  if (value.length <= maxLength) return value

  const suffix = '\n...truncated'
  let output = ''
  let open: string[] = []
  const closing = (tags: string[]) => [...tags].reverse().map(tag => `</${tag}>`).join('')
  const tokens = value.match(/<[^>]*>|&(?:#\d+|#x[\da-f]+|[a-z][\da-z]*);|[^<&]+|[<&]/gi) || []
  for (const token of tokens) {
    const nextOpen = [...open]
    const tag = token.match(/^<(\/?)([a-z][\da-z-]*)\b/i)
    if (tag) {
      const name = tag[2].toLowerCase()
      if (tag[1]) nextOpen.pop()
      else if (!/\/>$/.test(token) && !['br', 'hr', 'img'].includes(name)) nextOpen.push(name)
    }
    if (output.length + token.length + closing(nextOpen).length + suffix.length <= maxLength) {
      output += token
      open = nextOpen
      continue
    }
    if (!tag && !token.startsWith('&') && !token.startsWith('<')) {
      let part = token.slice(0, Math.max(0, maxLength - output.length - closing(open).length - suffix.length))
      if (/[\uD800-\uDBFF]$/.test(part)) part = part.slice(0, -1)
      output += part
    }
    break
  }
  return output + closing(open) + suffix
}

module.exports = { truncateTelegramHtml }
